return {
  apply(ctx) {
    const readTasks = async () => {
      // 注意: 若 fs.resolve 不展开 '~', 请改为绝对路径如 C:/Users/<你>/.dsh/downloads/tasks
      const dir = '~/.dsh/downloads/tasks'
      const fs = ctx.get('fs')
      if (!fs) return []
      try {
        const target = await fs.resolve(dir)
        const entries = await fs.listDir(target)
        const tasks = []
        for (const e of entries) {
          if (!e.name || !e.name.endsWith('.json')) continue
          try {
            const t = await fs.resolve(dir + '/' + e.name)
            const text = await fs.readText(t)
            const obj = JSON.parse(text)
            if (obj && obj.name) {
              obj.taskId = e.name.replace(/\.json$/, '')
              tasks.push(obj)
            }
          } catch (e2) { /* skip */ }
        }
        const rank = (t) => (t.status === 'downloading' || t.status === 'starting' || t.status === 'probing') ? 0 : 1
        tasks.sort((a, b) => rank(a) - rank(b) || ((b.startedAt || 0) - (a.startedAt || 0)))
        return tasks.slice(0, 20)
      } catch (e) { return [] }
    }
    const disposer = harness.handle('dl-tasks', async () => await readTasks())
    ctx.effect(() => disposer)
  },
}

